%EXAMPLE_SIMULATED  End-to-end run on a synthetic dataset: distribution comparison, model fits, held-out evaluation, group comparison.
%
%   Runs in a few minutes with a parallel pool. Outputs go to <repo>/output/simulated.
root = ttSetup(); outDir = fullfile(root, 'output', 'simulated'); if ~exist(outDir, 'dir'), mkdir(outDir); end
if isempty(gcp('nocreate')), parpool; end

% 1. data: four synthetic animals, two groups (B learns at half the rate), generated by the threshold-tracking actor
D = ttSimulateDataset('nAnimals', 4, 'seed', 1);
disp(D.sessions(1:8, {'animal', 'session', 'stage', 'phase', 'nCued', 'delayMean'}));

% 2. which lick-time distribution: cross-validated per session and per delay block
ttDistCV(D, outDir, 'families', {'lognormal', 'ln_exp', 'lnmix2'});
S = ttDistSummary(outDir);
disp(S.byPhase(S.byPhase.scheme == "forward" & S.byPhase.unitType == "session", {'phase', 'family', 'n', 'median_dLL', 'frac_best'}));

% 3. policy models: the core set, fitted per animal with an empirical-Bayes prior
ttFitAll(D, ttModelSet('core'), outDir, 'ebIter', 4);

% 4. held-out evaluation (first 70 % of each session fitted, last 30 % scored) and comparison tables
ttHeldOut(D, outDir, 'nSim', 2);
C = ttCompare(outDir);
disp(C.contrasts(C.contrasts.by == "phase", {'variant', 'level', 'n', 'd_ll', 'frac_ll'}));

% 5. does each model's own step predict the next lick
[~, U] = ttUpdateTest(outDir);
disp(U(:, {'variant', 'phase', 'n', 'median_r_shift', 'frac_above_null', 'median_r_step'}));

% 6. group comparison on the fitted learning rate of the threshold-tracking actor
P = ttParamTable(outDir, 'lnexp_ThistoryLearn_Efixed_Rthreshold');
G = ttGroupCompare(P, 'alpha_up', 'A', 'B', 'by', 'stage', 'transform', @log10);
disp(G(:, {'level', 'nAnimalsA', 'nAnimalsB', 'medianA', 'medianB', 'diff', 'ci_lo', 'ci_hi', 'p_perm'}));
[M, fig] = ttGroupTrajectories(P, 'alpha_up', 'x', 'stageIndex', 'stage', 'delayTraining', 'transform', @log10, 'plot', true, 'label', 'log10 learning rate');
print(fig, '-dpng', '-r130', fullfile(outDir, 'trajectory_alpha_up.png')); close(fig);

% 7. one session of one animal
L = load(fullfile(outDir, 'fits', 'SIM01_lnexp_ThistoryLearn_Efixed_Rthreshold.mat')); L0 = load(fullfile(outDir, 'fits', 'SIM01_lnexp_Tfixed_Efixed.mat'));
fig = ttPlotSession(L.Res, L.Res.params.session(4), 'compare', L0.Res); print(fig, '-dpng', '-r130', fullfile(outDir, 'session_example.png')); close(fig);
